// Génère 3 questions contextuelles selon la semaine
const now = new Date();
const weekNum = Math.ceil(now.getDate() / 7);

// Banque de questions — varie chaque semaine
const banques = {
  q1: [
    "Un client ou projet dont tu es particulièrement fière cette semaine ?",
    "Une bonne nouvelle côté fournisseur Vietnam cette semaine ?",
    "Un succès récent que tu aimerais partager avec ta communauté LinkedIn ?",
    "Quel client ou secteur t'a surpris positivement cette semaine ?"
  ],
  q2: [
    "Un défi ou obstacle que tu as surmonté (ou qui t'attend) ?",
    "Quelque chose qui t'a compliqué la tâche cette semaine dans le sourcing ?",
    "Un problème logistique ou douanier récent qui illustre les défis du métier ?",
    "Une négociation difficile ou un point de tension avec un fournisseur ?"
  ],
  q3: [
    "Un conseil ou insight à partager sur le sourcing Vietnam pour les PME françaises ?",
    "Quelque chose que tu ferais différemment si tu recommençais dans ce métier ?",
    "Un mythe sur l'import Vietnam que tu voudrais démystifier ?",
    "Ta vision pour les 6 prochains mois sur l'activité import France-Vietnam ?"
  ]
};

const idx = (weekNum - 1) % 4;
const q1 = banques.q1[idx];
const q2 = banques.q2[idx];
const q3 = banques.q3[idx];

const semaine = new Date(now);
semaine.setHours(0,0,0,0);
semaine.setDate(now.getDate() - now.getDay() + 1); // lundi

const message = `🗓 <b>Check-in hebdomadaire CNL Sourcing</b>\n\nBonjour Anna ! 3 petites questions pour personnaliser tes posts LinkedIn de la semaine. Réponds quand tu peux, en 1 ou plusieurs messages. Je rassemble tout.\n\n<b>1.</b> ${q1}\n\n<b>2.</b> ${q2}\n\n<b>3.</b> ${q3}\n\n<i>Réponds directement dans ce chat. Tes réponses enrichiront les posts publiés cette semaine.</i>`;

return [{ json: { message, q1, q2, q3, semaine: semaine.toISOString().split('T')[0] } }];
